require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/TicketingModule.php';
if(PHP_SAPI!=='cli'){Auth::requireLogin();if(!Auth::canManageSystemTools()){http_response_code(403);exit('برای نصب تیکتینگ مجوز مدیریت سیستم لازم است.');}if($_SERVER['REQUEST_METHOD']!=='POST'){$pageTitle='نصب تیکتینگ';require __DIR__.'/../views/partials/admin-header.php';?><section class="card"><h1>نصب امن تیکتینگ</h1><p>فقط جدول‌ها و مجوزهای مفقود ساخته می‌شوند؛ هیچ داده‌ای حذف نمی‌شود.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><button class="btn btn-primary">اجرای نصب</button></form></section><?php require __DIR__.'/../views/partials/admin-footer.php';exit;}if(!Auth::verifyCsrf($_POST['csrf_token']??null)){http_response_code(419);exit('درخواست معتبر نیست.');}}
